INSERT INTO knowledge_documents (title, content, source, category, tags, isActive, createdAt, updatedAt) 
VALUES ('قانون الأراضي العثماني - المادة 4: الأراضي الموقوفة', 'الأراضي الموقوفة هي الأراضي التي أوقفها أصحابها على جهة بر أو خير. ولا يجوز بيعها أو رهنها أو توريثها، وإنما تبقى على ملك الموقوف عليهم أو الجهة الموقوف عليها.', 'قانون الأراضي العثماني (1858)', 'law', 'قانون الأراضي، الوقف، الأراضي الموقوفة', 1, FROM_UNIXTIME(1767919441), FROM_UNIXTIME(1767919441));

